      "path": "plugins/dsh-strict-spec/src/client.ts",
      "content": "/**\n * Client entry of dsh-plugin-strict-spec, served as /plugins/<name>/client.js.\n *\n * The entry registers both strict document surfaces. The left-sidebar\n * panel: a sidebar.panellist row (icon plus locale-thunked label) whose id\n * matches the `main` keyed registration, so selecting the row opens the\n * two-pane strict documents page. Because the main keyed slot receives no\n * Session binding while every remote.workspaceFiles call needs a sessionId,\n * the page owns an explicit Session picker: the entry injects the host's\n * session and workspace service faces and adapts them once into the\n * plugin-owned picker seam, next to the discovery model's remote port, so\n * model modules stay dsh-free. The root-scoped page selection store\n * survives page remounts, so reopening the page restores the chosen\n * Session and the selected document.\n *\n * The right-sidebar tab: the sidebarRightTabs registry carries the static\n * tab type (the package id, a page kind opened by kind, a thunked title,\n * and one guide entry that makes it discoverable), and the body registers\n * in the sidebar.right.pane.tab keyed slot through the declaration-aware\n * inject path. That seat is Session-scoped: its inject factory receives\n * the sessionId of the Session surface rendering the tab and returns one\n * per-Session tab surface from the model's cache, so the tab body binds to\n * the active Session, follows Session switches with the default\n * unmount-on-hide teardown closing the previous Session's watches, and\n * never shares viewer stores with another Session. Both registrations go\n * through ctx.slots.inject, and every user-visible string is registered in\n * both the zh and en catalogs of the `strictSpec` namespace.\n *\n * Both surfaces also carry the milestone goal launcher: the entry adapts\n * the `remote.commands` face once into the plugin-owned command port and\n * keeps one launcher per Session, which the tab surface takes for its bound\n * Session and the page takes for the Session its picker shows, so the\n * roadmap index launch control always submits `/goal` to that Session.\n */\nimport type { Context as ClientContext } from \"@deepseek-ai/cordis\";\n// Type-only contract merges: the runtime halves belong to the host shell and\n// create no module request in the bundle (type-only imports are erased). The\n// api controller merges declare the ctx.sessions and ctx.workspaces service\n// faces the Session picker seam adapts; the sidebar-right merge declares the\n// ctx.sidebarRightTabs registry the tab type registers through. Their\n// packages stay type-only devDependencies, so the bundle gains no runtime\n// require for them.\nimport type {} from \"@deepseek-ai/dsh-api-session-controller/client\";\nimport type {} from \"@deepseek-ai/dsh-api-workspace-controller/client\";\n// The generated remote-client half composes the `workspaceFiles` namespace\n// onto ctx.remote; loading its types is what makes the remote port adapter\n// type-check against the real face.\nimport type {} from \"@deepseek-ai/dsh-api-workspace-files/remote\";\n// The commands remote-client half composes the `commands` namespace the\n// milestone goal launcher submits its `/goal` line through.\nimport type {} from \"@deepseek-ai/dsh-commands/remote\";\nimport type {} from \"@deepseek-ai/dsh-client-locale/client\";\nimport type {} from \"@deepseek-ai/dsh-client-ui-layout/client\";\nimport type {} from \"@deepseek-ai/dsh-client-ui-renderer/client\";\nimport type {} from \"@deepseek-ai/dsh-client-ui-sidebar-right/client\";\nimport type {} from \"@deepseek-ai/dsh-client-ui-sidebar/client\";\nimport type { ReactNode } from \"react\";\nimport { jsx } from \"react/jsx-runtime\";\nimport type { PropsLocale, PropsRuntime } from \"@deepseek-ai/dsh-client-ui-slots\";\nimport { PanelIcon } from \"./client/PanelIcon.tsx\";\nimport { StrictDocumentsPage } from \"./client/StrictDocumentsPage.tsx\";\nimport { StrictDocumentsTab } from \"./client/StrictDocumentsTab.tsx\";\nimport { en, zh } from \"./client/locales.ts\";\nimport { createPageController, createPageSelectionStore, createSessionCatalogPort } from \"./model/picker.ts\";\nimport { createTabSurfaces } from \"./model/tab.ts\";\nimport { createRemotePort } from \"./model/port.ts\";\nimport { createCommandPort, createGoalLaunchers } from \"./model/goalLaunch.ts\";\nimport { createViewerStores } from \"./model/store.ts\";\n\ndeclare module \"@deepseek-ai/dsh-client-ui-slots\" {\n  interface LocaleNamespaceMap {\n    /** Strict document viewer copy. */\n    strictSpec: keyof typeof zh;\n  }\n}\n\n/** Services required before the panel registrations run. */\nexport const inject = [\"slots\", \"locale\", \"remote\", \"remote.workspaceFiles\", \"remote.commands\", \"sessions\", \"workspaces\", \"sidebarRightTabs\"];\n\n/** The shared identity of the sidebar row and its main panel. */\nconst PANEL_ID = \"strict-spec\";\n\n/** Row order after the shipped global panels. */\nconst PANEL_ORDER = 900;\n\n/** The tab type's implementation identity in the right-sidebar registry. */\nconst TAB_ID = \"dsh-plugin-strict-spec\";\n\n/** The tab's kind: a page type opened by kind, matching no resource address. */\nconst TAB_KIND = \"strict-spec-documents\";\n\n/** Guide entry order among the shipped types' entries. */\nconst TAB_GUIDE_ORDER = 90;\n\n/**\n * Registers the dictionaries, the strict documents panel row with its main\n * page, and the Session-bound strict documents right-sidebar tab.\n *\n * The slot registrations go through `ctx.slots.inject`, the\n * declaration-aware installation path: a dynamic plugin fiber can activate\n * before the shell entries that declare `sidebar.panellist`, `main`, and\n * `sidebar.right.pane.tab` have committed their children tables, and\n * registering into an undeclared slot throws. `inject` runs the\n * registration the moment the declaration is live (immediately when it\n * already is) and collects the disposers on declaration collapse and fiber\n * unload. The tab-type registration goes through `ctx.effect` around the\n * registry's own disposer, the same two-stage path the host's shipped tab\n * types use.\n *\n * @param ctx - client root context.\n */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(\"strictSpec\", { zh, en }), \"dsh-plugin-strict-spec: dictionaries\");\n  const t = ctx.locale.bind(\"strictSpec\");\n  // The seams both surfaces consume: one stateless remote workspace-files\n  // port shared by the page viewer and every per-Session tab surface, the\n  // session catalog adapted from the injected service faces, and the\n  // root-scoped page selection that survives page remounts. Created once\n  // per client load so each surface keeps its own viewer state.\n  const remotePort = createRemotePort({ workspaceFiles: ctx.remote.workspaceFiles });\n  const viewer = createViewerStores(remotePort);\n  const page = createPageSelectionStore();\n  const controller = createPageController(viewer, page.store);\n  const picker = createSessionCatalogPort(ctx.sessions, ctx.workspaces);\n  // The milestone goal launchers: one per Session over the one command\n  // port, shared by the page and the tab surfaces so both entry points\n  // show the same Session's launch state.\n  const goalLaunchers = createGoalLaunchers(createCommandPort({ commands: ctx.remote.commands }));\n  const tabSurfaces = createTabSurfaces(remotePort, goalLaunchers);\n  // The main-slot occupant closes over the seams so the page component\n  // itself stays a pure props consumer; building the element through the\n  // shared jsx-runtime factory keeps the bundle off a bare react require\n  // the host's frozen module table does not share. The tab body needs no\n  // wrapper: the seat's per-Session inject factory supplies its surface\n  // and the locale registration supplies its translate function.\n  const PageWithSeams = (slotProps: PropsRuntime<\"main\"> & PropsLocale<\"strictSpec\">): ReactNode =>\n    jsx(StrictDocumentsPage, { ...slotProps, picker, pageSelection: page.store, pageActions: page.actions, controller, viewer, goalLaunchers });\n  ctx.slots.inject(\"sidebar.panellist\", () =>\n    ctx.slots.register(\n      {\n        name: \"sidebar.panellist\",\n        id: PANEL_ID,\n        order: PANEL_ORDER,\n        label: () => t(\"panel.title\"),\n        registrant: \"dsh-plugin-strict-spec\",\n      },\n      PanelIcon,\n    ),\n  );\n  ctx.slots.inject(\"main\", () =>\n    ctx.slots.register(\n      { name: \"main\", key: PANEL_ID, locale: \"strictSpec\", registrant: \"dsh-plugin-strict-spec\" },\n      PageWithSeams,\n    ),\n  );\n  // Stage one of the tab registration: the static type with its guide\n  // entry, owned by the registry for this fiber's lifetime. The default\n  // extension priority band is the right one for a type from outside the\n  // product, and omitting patterns makes it a page type opened by kind.\n  ctx.effect(\n    () =>\n      ctx.sidebarRightTabs.register({\n        id: TAB_ID,\n        kind: TAB_KIND,\n        title: () => t(\"tab.title\"),\n        guide: [\n          {\n            id: \"open\",\n            order: TAB_GUIDE_ORDER,\n            title: () => t(\"tab.guide-title\"),\n            description: () => t(\"tab.guide-description\"),\n          },\n        ],\n      }),\n    \"dsh-plugin-strict-spec: sidebar-right tab type\",\n  );\n  // Stage two: the body under the type's own id. The seat calls the inject\n  // factory with the sessionId of the Session surface rendering the tab,\n  // and the factory returns that Session's cached surface, so each surface\n  // binds one Session and its teardown runs on body unmount. The collected\n  // disposer also clears the whole surface cache, so an unloaded fiber\n  // leaks no watches.\n  ctx.slots.inject(\"sidebar.right.pane.tab\", () => {\n    const unregister = ctx.slots.register(\n      {\n        name: \"sidebar.right.pane.tab\",\n        key: TAB_ID,\n        locale: \"strictSpec\",\n        registrant: \"dsh-plugin-strict-spec\",\n        inject: (sessionId: string) => ({ surface: tabSurfaces.get(sessionId) }),\n      },\n      StrictDocumentsTab,\n    );\n    return () => {\n      unregister();\n      tabSurfaces.dispose();\n    };\n  });\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/model/port.ts",
      "content": "/**\n * The workspace-files port: the only seam the discovery model uses to reach\n * the Session workspace.\n *\n * The interface mirrors the wire contract of the pinned dsh release's\n * `remote.workspaceFiles` namespace — every method takes the sessionId first,\n * because the Host derives the workspace root from it; `list` speaks\n * workspace-relative paths and reports direct children only, cut to the entry\n * cap with a `truncated` flag and no paging; `readBytes` without a range\n * returns the complete file under the complete-file cap; and `changes` yields\n * watch frames for one file or one directory's direct entries and is not\n * recursive. Expressing that seam as a plugin-owned interface keeps every\n * model module free of dsh imports, so the whole model runs under\n * `bun test/run.ts` against a scripted fake while the client passes the real\n * remote face through `createRemotePort` unchanged.\n */\n\n/** One direct child of a listed workspace directory, as the wire reports it. */\nexport interface DirectoryEntry {\n  /** Basename inside the listed directory. */\n  readonly name: string;\n  /** What the child resolves to: file, directory, or anything else. */\n  readonly type: \"file\" | \"directory\" | \"other\";\n  /** Byte size, present only for a regular file whose backend reports it. */\n  readonly size?: number;\n}\n\n/** Direct children of one workspace directory, cut to the host entry cap. */\nexport interface DirectoryListing {\n  /** The listed directory as a workspace-relative path; empty for the root. */\n  readonly path: string;\n  /** Direct children in the backend's stable name order. */\n  readonly entries: readonly DirectoryEntry[];\n  /** Whether the entry cap dropped children from `entries`; list has no paging. */\n  readonly truncated: boolean;\n}\n\n/** One page of a workspace text file: lines joined by `\\n`, 1-based offset. */\nexport interface TextPage {\n  /** First line of the page, as requested. */\n  readonly offset: number;\n  /** The page's lines joined by `\\n`, without a terminator after the last one. */\n  readonly text: string;\n  /** How many lines the page holds. */\n  readonly lines: number;\n  /** Whether the page includes the file's last line. */\n  readonly eof: boolean;\n}\n\n/** One byte window of a workspace file; `data` holds the read bytes raw. */\nexport interface ByteWindow {\n  /** First byte of the window, as requested. */\n  readonly offset: number;\n  /** Native file bytes; the complete file when no range was requested. */\n  readonly data: Uint8Array;\n  /** Whether the window includes the file's last byte. */\n  readonly eof: boolean;\n}\n\n/** A filesystem invalidation of one watched target, as the wire reports it. */\nexport type FileChange =\n  | { readonly absolutePath: string; readonly version: string }\n  | { readonly absolutePath: string; readonly absent: true };\n\n/** One frame of a watch generation: readiness, then invalidations. */\nexport type WatchFrame =\n  | { readonly kind: \"ready\" }\n  | { readonly kind: \"change\"; readonly change: FileChange };\n\n/** A line window one `read` may request. */\nexport interface TextRange {\n  readonly offset?: number;\n  readonly limit?: number;\n}\n\n/** A byte window one `readBytes` may request. */\nexport interface ByteRange {\n  readonly offset?: number;\n  readonly length?: number;\n}\n\n/** Target resolution and optional byte range for one binary read. */\nexport interface ByteReadOptions {\n  readonly range?: ByteRange;\n}\n\n/**\n * The `workspaceFiles` methods the discovery model calls, each taking the\n * sessionId first and naming files by workspace-relative paths.\n */\nexport interface WorkspaceFilesPort {\n  /** List the direct children of one workspace directory. */\n  list(sessionId: string, path: string, signal?: AbortSignal): Promise<DirectoryListing>;\n  /** Read one page of lines from a workspace text file. */\n  read(sessionId: string, path: string, range?: TextRange, signal?: AbortSignal): Promise<TextPage>;\n  /** Read a byte window, or the complete file when no range is given. */\n  readBytes(sessionId: string, path: string, options?: ByteReadOptions, signal?: AbortSignal): Promise<ByteWindow>;\n  /** Watch one file or one directory's direct entries; not recursive. */\n  changes(sessionId: string, path: string, signal?: AbortSignal): AsyncIterable<WatchFrame>;\n}\n\n/**\n * The wire's result envelope, mirrored structurally: every generated\n * workspace-files method resolves to ok-with-value or fails-with-error, and\n * the Remote face folds carrier failures into the error branch, so the port\n * adapter unwraps instead of catching.\n */\nexport type RemoteOutcome<T> = { readonly ok: true; readonly value: T } | { readonly ok: false; readonly error: { readonly code?: string; readonly message?: string } };\n\n/**\n * The structural slice of the generated client remote the port adapts. The\n * shapes are the wire's own — `read`'s range and `readBytes`' options are\n * required objects on the wire, where the host dereferences them without a\n * guard, and every method resolves the wire's result envelope — so a real\n * `ctx.remote` satisfies them without any dsh import in this module.\n */\nexport interface RemoteWorkspaceFilesFace {\n  readonly workspaceFiles: {\n    list(sessionId: string, path: string, signal?: AbortSignal): Promise<RemoteOutcome<DirectoryListing>>;\n    read(sessionId: string, path: string, range: TextRange, signal?: AbortSignal): Promise<RemoteOutcome<TextPage>>;\n    readBytes(sessionId: string, path: string, options: ByteReadOptions, signal?: AbortSignal): Promise<RemoteOutcome<ByteWindow>>;\n    changes(sessionId: string, path: string, signal?: AbortSignal): AsyncIterable<WatchFrame>;\n  };\n}\n\n/**\n * Unwraps one wire outcome: the ok branch's value resolves, the error\n * branch's failure throws carrying its code, which is what\n * workspaceFileErrorCode reads. Only assembly faults reject on the wire\n * itself, and those keep their own throw shape.\n */\nfunction unwrapOutcome<T>(outcome: RemoteOutcome<T>): T {\n  if (outcome.ok) {\n    return outcome.value;\n  }\n  throw outcome.error;\n}\n\n/**\n * Adapts the generated client remote face to the model's port, normalizing\n * omitted option objects to the empty objects the wire requires and the\n * wire's result envelope to plain values and thrown failures: a call that\n * passes no range or options still reaches the host as `{}`, never as\n * `undefined`, and a failed call rejects with the failure the model's\n * error-code reader expects.\n */\nexport function createRemotePort(remote: RemoteWorkspaceFilesFace): WorkspaceFilesPort {\n  return {\n    list: async (sessionId, path, signal) => unwrapOutcome(await remote.workspaceFiles.list(sessionId, path, signal)),\n    read: async (sessionId, path, range, signal) => unwrapOutcome(await remote.workspaceFiles.read(sessionId, path, range ?? {}, signal)),\n    readBytes: async (sessionId, path, options, signal) => unwrapOutcome(await remote.workspaceFiles.readBytes(sessionId, path, options ?? {}, signal)),\n    changes: (sessionId, path, signal) => remote.workspaceFiles.changes(sessionId, path, signal),\n  };\n}\n\n/**\n * The error code of a failed workspace-files call, when the thrown error\n * carries one. Callers branch on the code — `not-found`, `outside-workspace`,\n * `watch-unsupported`, `too-large`, `not-text`, `not-regular-file`,\n * `not-directory` — never on message text.\n */\nexport function workspaceFileErrorCode(error: unknown): string | undefined {\n  if (typeof error === \"object\" && error !== null && \"code\" in error) {\n    const code = (error as { code?: unknown }).code;\n    if (typeof code === \"string\" && code.length > 0) {\n      return code;\n    }\n  }\n  return undefined;\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/model/loader.ts",
      "content": "/**\n * The document loader: reads one strict document completely and parses it\n * with the plugin's bundled YAML parser.\n *\n * A complete read prefers `readBytes` with no range — one round trip that\n * returns the whole file under the host's complete-file cap — and decodes the\n * bytes as UTF-8 itself. A byte read the cap refuses (`too-large`) falls back\n * to `read` line pages walked until eof; both paths converge on the same\n * string handed to the parser, so parse behavior never depends on which path\n * served the bytes. The result is either parsed data or a failure: a parse\n * error located by 1-based line and column, or a read error classified by the\n * workspace-files error code.\n *\n * Parsing uses the YAML 1.2 core schema: the viewer contract shows declared\n * values exactly as written, and the core schema keeps timestamp-like and\n * yes/no-like scalars as their literal strings instead of the YAML 1.1\n * object forms the default schema would substitute.\n */\nimport { CORE_SCHEMA, load } from \"js-yaml\";\nimport type { DocumentLoadResult, LocatedParseError, ReadError } from \"./nodes.ts\";\nimport { workspaceFileErrorCode } from \"./port.ts\";\nimport type { WorkspaceFilesPort } from \"./port.ts\";\nimport { declaredArtifactType } from \"./classifier.ts\";\n\n/** A UTF-8 decoder that refuses invalid byte sequences instead of replacing them. */\nconst utf8Decoder = new TextDecoder(\"utf-8\", { fatal: true });\n\n/** Maps one thrown js-yaml error to a parse error located by 1-based position. */\nfunction toLocatedParseError(error: unknown, raw: string): LocatedParseError {\n  const mark = (error as { mark?: { line?: unknown; column?: unknown } | null } | null)?.mark;\n  const line = typeof mark?.line === \"number\" && mark.line >= 0 ? mark.line + 1 : 1;\n  const column = typeof mark?.column === \"number\" && mark.column >= 0 ? mark.column + 1 : 1;\n  const message = error instanceof Error ? error.message : String(error);\n  return { kind: \"parse\", message, line, column, raw };\n}\n\n/** Maps one thrown workspace-files error to a read error classified by code. */\nfunction toReadError(error: unknown): ReadError {\n  return { kind: \"read\", code: workspaceFileErrorCode(error) ?? \"unknown\" };\n}\n\n/**\n * Reads the complete file through paged `read` until eof. Pages carry lines\n * joined by `\\n` without a terminator after the last one, so consecutive\n * pages concatenate over one newline.\n */\nasync function readAllPages(\n  port: WorkspaceFilesPort,\n  sessionId: string,\n  path: string,\n  signal?: AbortSignal,\n): Promise<string> {\n  const parts: string[] = [];\n  let offset = 1;\n  for (;;) {\n    const page = await port.read(sessionId, path, { offset }, signal);\n    if (page.lines > 0) {\n      parts.push(page.text);\n      offset += page.lines;\n    } else if (!page.eof) {\n      // A page that holds no lines and no eof would loop forever; treat the\n      // walk as failed rather than hanging on a misbehaving backend.\n      throw new Error(\"workspace read page reported neither lines nor eof\");\n    }\n    if (page.eof) {\n      return parts.length === 0 ? \"\" : parts.join(\"\\n\");\n    }\n  }\n}\n\n/**\n * Loads one strict document: reads the complete file — `readBytes` without a\n * range decoded as UTF-8, falling back to paged `read` until eof when the\n * byte read is refused as too large — and parses the text with the bundled\n * parser. Returns the parsed data with its declared artifact_type, or a\n * located parse error or classified read error.\n */\nexport async function loadDocument(\n  port: WorkspaceFilesPort,\n  sessionId: string,\n  path: string,\n  signal?: AbortSignal,\n): Promise<DocumentLoadResult> {\n  let text: string;\n  try {\n    const window = await port.readBytes(sessionId, path, {}, signal);\n    try {\n      text = utf8Decoder.decode(window.data);\n    } catch {\n      // The byte read carries no text gating; invalid UTF-8 surfaces here.\n      return { ok: false, error: { kind: \"read\", code: \"workspace-file/not-text\" } satisfies ReadError };\n    }\n  } catch (byteError) {\n    if (workspaceFileErrorCode(byteError) !== \"workspace-file/too-large\") {\n      return { ok: false, error: toReadError(byteError) };\n    }\n    try {\n      text = await readAllPages(port, sessionId, path, signal);\n    } catch (pageError) {\n      return { ok: false, error: toReadError(pageError) };\n    }\n  }\n  try {\n    const data = load(text, { schema: CORE_SCHEMA });\n    return { ok: true, data, artifactType: declaredArtifactType(data) };\n  } catch (parseError) {\n    return { ok: false, error: toLocatedParseError(parseError, text) };\n  }\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/client/GoalLaunchControl.tsx",
      "content": "/**\n * The milestone goal launch control the roadmap index view renders: one\n * button that opens an inline confirmation presenting the exact objective\n * and the target Session, then submits through the bound Session's\n * launcher, showing the pending, launched, and refused states inline.\n *\n * The control renders nothing without a launcher, so a context-free render\n * or a surface bound to no Session shows no launch affordance. The view is\n * split per the plugin conventions: `GoalLaunchControlView` is hook-free —\n * it takes the launch state and returns elements whose handlers a suite can\n * fire without a DOM — and `GoalLaunchControl` only reads the launcher's\n * store, with an identity-stable fallback so its hook structure never\n * varies on the launcher's presence. The objective is the command payload\n * itself and renders verbatim, identical in every locale; every other\n * visible string renders through the strictSpec catalogs.\n */\nimport { useSyncExternalStore, type ReactNode } from \"react\";\nimport { Button } from \"@deepseek-ai/dsh-client-ui-primitives\";\nimport type { Translate } from \"@deepseek-ai/dsh-client-ui-slots\";\nimport type { GoalLaunchActions, GoalLaunchRefusal, GoalLaunchState, GoalLauncher } from \"../model/goalLaunch.ts\";\nimport type { StrictSpecKey } from \"./locales.ts\";\nimport styles from \"./RoadmapViews.module.css\";\n\n/** Props the hook-free launch control view consumes. */\nexport interface GoalLaunchControlViewProps {\n  /** The launch state to render. */\n  readonly state: GoalLaunchState;\n  /** The exact objective a confirmed launch submits. */\n  readonly objective: string;\n  /** The Session a confirmed launch submits to. */\n  readonly sessionId: string;\n  /** The launcher actions the buttons call. */\n  readonly actions: GoalLaunchActions;\n  /** The strictSpec translate function. */\n  readonly t: Translate<StrictSpecKey>;\n}\n\n/** The inline message one refusal renders. */\nfunction refusalMessage(refusal: GoalLaunchRefusal, t: Translate<StrictSpecKey>): string {\n  switch (refusal.kind) {\n    case \"refused\":\n      return t(\"roadmap.goal-refused\", { reason: refusal.text });\n    case \"unavailable\":\n      return t(\"roadmap.goal-unavailable\");\n    case \"failed\":\n      return t(\"roadmap.goal-failed\", { reason: refusal.message });\n  }\n}\n\n/** Renders the launch control for one state, without hooks. */\nexport function GoalLaunchControlView(props: GoalLaunchControlViewProps): ReactNode {\n  const { state, objective, sessionId, actions, t } = props;\n  if (state.phase === \"confirming\" || state.phase === \"pending\") {\n    const pending = state.phase === \"pending\";\n    return (\n      <div className={styles.goalLaunch} role=\"group\" aria-label={t(\"roadmap.goal-launch\")}>\n        <div className={styles.goalConfirmTitle}>{t(\"roadmap.goal-confirm-title\")}</div>\n        <div className={styles.goalConfirmSession}>{t(\"roadmap.goal-confirm-session\", { sessionId })}</div>\n        <pre className={styles.goalObjective}>{objective}</pre>\n        <div className={styles.goalActions}>\n          <Button variant=\"primary\" size=\"sm\" disabled={pending} onClick={() => void actions.confirm()}>\n            {pending ? t(\"roadmap.goal-pending\") : t(\"roadmap.goal-confirm\")}\n          </Button>\n          <Button variant=\"ghost\" size=\"sm\" disabled={pending} onClick={() => actions.cancel()}>\n            {t(\"roadmap.goal-cancel\")}\n          </Button>\n        </div>\n      </div>\n    );\n  }\n  return (\n    <div className={styles.goalLaunch}>\n      <div className={styles.goalActions}>\n        <Button variant=\"outline\" size=\"sm\" onClick={() => actions.request()}>\n          {t(\"roadmap.goal-launch\")}\n        </Button>\n        <span className={styles.goalHint}>{t(\"roadmap.goal-launch-hint\")}</span>\n      </div>\n      {state.phase === \"launched\" ? (\n        <div className={styles.goalNotice} role=\"status\">{t(\"roadmap.goal-launched\")}</div>\n      ) : state.phase === \"refused\" ? (\n        <div className={styles.goalRefusal} role=\"alert\">{refusalMessage(state.refusal, t)}</div>\n      ) : null}\n    </div>\n  );\n}\n\n/** The identity-stable idle snapshot the fallback store serves. */\nconst IDLE_STATE: GoalLaunchState = { phase: \"idle\" };\n\n/** The store read when no launcher is wired, keeping one hook shape. */\nconst FALLBACK_STATE_STORE = {\n  subscribe: (): (() => void) => () => undefined,\n  getSnapshot: (): GoalLaunchState => IDLE_STATE,\n};\n\n/** Props the launch control consumes. */\nexport interface GoalLaunchControlProps {\n  /** The bound Session's launcher; absent renders no control. */\n  readonly launcher: GoalLauncher | undefined;\n  /** The strictSpec translate function. */\n  readonly t: Translate<StrictSpecKey>;\n}\n\n/** Renders the launch control from the bound Session's launcher store. */\nexport function GoalLaunchControl(props: GoalLaunchControlProps): ReactNode {\n  const { launcher, t } = props;\n  const store = launcher === undefined ? FALLBACK_STATE_STORE : launcher.state;\n  const state = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);\n  if (launcher === undefined) {\n    return null;\n  }\n  return <GoalLaunchControlView state={state} objective={launcher.objective} sessionId={launcher.sessionId} actions={launcher.actions} t={t} />;\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/model/goalLaunch.ts",
      "content": "/**\n * The milestone goal launcher: the one viewer control that hands work to a\n * Session, as the roadmap index view's launch control.\n *\n * Launching submits exactly one `/goal` command line to the bound Session\n * through a plugin-owned command port that mirrors the pinned dsh release's\n * `remote.commands.execute` wire contract — the receiving agent's\n * sessionId, the full command line, and the submitted attachments, which\n * the wire requires and this launcher always sends empty. Going through the\n * command plane instead of the goal service keeps the launch identical to a\n * typed `/goal`: the host creates and arms the goal, logs the command run\n * durably, and reports its own refusal text when an unfinished goal already\n * exists. The objective is one fixed English string, so the confirmation\n * shows exactly what the Session receives.\n *\n * Each Session owns one launcher with a snapshot store the control renders\n * from: idle, confirming, pending, launched, or refused. Confirming is\n * single-flight — a second confirm or request while a submission is pending\n * does nothing — and a refusal or success returns the control to a usable\n * state. The launcher never reads or writes workspace files. Modules here\n * stay dsh-free like the rest of the model, testable under bun test/run.ts\n * with a scripted port.\n */\nimport { createSnapshotStore } from \"@deepseek-ai/dsh-client-store\";\nimport type { SnapshotStore } from \"@deepseek-ai/dsh-client-store\";\nimport type { RemoteOutcome } from \"./port.ts\";\n\n/**\n * The fixed goal objective: repeatedly run strict-roadmap-recommend until\n * the milestone its first recommendation selects is complete, with every\n * stop condition stated so the goal completes or blocks instead of idling.\n */\nexport const MILESTONE_GOAL_OBJECTIVE =\n  \"Repeatedly run the strict-roadmap-recommend skill until one roadmap milestone is complete. \"\n  + \"In the first round, run it without a milestone hint; the milestone that owns the planned change it recommends is the target milestone. \"\n  + \"In every later round, pass the target milestone id as the milestone hint, so the recommendation runs with --milestone <target-milestone-id>, \"\n  + \"and carry each recommended change through strict-spec-auto to archive. \"\n  + \"Complete the goal once strict-spec-cli roadmap-status reports every planned change of the target milestone complete. \"\n  + \"Block the goal, stating the reason, when the recommendation reports roadmap-error, refine-milestone, or no-candidate before the target milestone is complete, \"\n  + \"or when a created change has open questions that need a human answer.\";\n\n/** The exact command line one confirmed launch submits. */\nexport const MILESTONE_GOAL_COMMAND_LINE = `/goal ${MILESTONE_GOAL_OBJECTIVE}`;\n\n/** A settled command's normalized result, as the wire reports it. */\nexport type CommandResult = { readonly kind: \"success\"; readonly text?: string } | { readonly kind: \"error\"; readonly text: string };\n\n/** What one command submission settled as, from the launcher's view. */\nexport type CommandOutcome =\n  | { readonly kind: \"executed\"; readonly result: CommandResult }\n  | { readonly kind: \"unknown-command\" };\n\n/** The command plane the launcher submits through, keyed by sessionId. */\nexport interface CommandPort {\n  /**\n   * Execute one command line on the Session's agent. Resolves with the\n   * handler's result, or `unknown-command` when the line names no command\n   * the Session offers; rejects when the call itself fails.\n   */\n  execute(sessionId: string, line: string): Promise<CommandOutcome>;\n}\n\n/**\n * The structural slice of the generated client remote the command port\n * adapts: the wire's `commands.execute` with its required attachments\n * array, resolving the wire's result envelope whose value is the settled\n * execution or `undefined` for an unknown or malformed command line.\n */\nexport interface RemoteCommandsFace {\n  readonly commands: {\n    execute(\n      agentId: string,\n      line: string,\n      submittedAttachments: readonly never[],\n      signal?: AbortSignal,\n    ): Promise<RemoteOutcome<{ readonly result: CommandResult } | undefined>>;\n  };\n}\n\n/**\n * Adapts the generated client remote face to the command port: the\n * required attachments array always reaches the host as `[]`, an\n * `undefined` value becomes `unknown-command`, and a failed envelope\n * rejects with the wire's error.\n */\nexport function createCommandPort(remote: RemoteCommandsFace): CommandPort {\n  return {\n    execute: async (sessionId, line) => {\n      const outcome = await remote.commands.execute(sessionId, line, []);\n      if (!outcome.ok) {\n        throw outcome.error;\n      }\n      return outcome.value === undefined ? { kind: \"unknown-command\" } : { kind: \"executed\", result: outcome.value.result };\n    },\n  };\n}\n\n/** Why the bound Session did not accept a launch. */\nexport type GoalLaunchRefusal =\n  /** The Session's `/goal` handler refused, with the text it reported. */\n  | { readonly kind: \"refused\"; readonly text: string }\n  /** The Session offers no `/goal` command. */\n  | { readonly kind: \"unavailable\" }\n  /** The submission call itself failed. */\n  | { readonly kind: \"failed\"; readonly message: string };\n\n/** The launch control's state for one Session. */\nexport type GoalLaunchState =\n  | { readonly phase: \"idle\" }\n  | { readonly phase: \"confirming\" }\n  | { readonly phase: \"pending\" }\n  | { readonly phase: \"launched\" }\n  | { readonly phase: \"refused\"; readonly refusal: GoalLaunchRefusal };\n\n/** The actions the launch control calls. */\nexport interface GoalLaunchActions {\n  /** Open the confirmation; ignored while confirming or pending. */\n  request(): void;\n  /** Close the confirmation without submitting; ignored unless confirming. */\n  cancel(): void;\n  /**\n   * Submit the objective once; ignored unless confirming, so a repeated\n   * confirm while pending submits nothing. Resolves once the submission\n   * settles.\n   */\n  confirm(): Promise<void>;\n}\n\n/** One Session's launcher: what the roadmap index control renders. */\nexport interface GoalLauncher {\n  /** The Session a confirmed launch submits to. */\n  readonly sessionId: string;\n  /** The exact objective the confirmation shows and the command carries. */\n  readonly objective: string;\n  /** The control's current state. */\n  readonly state: SnapshotStore<GoalLaunchState>;\n  /** The control's actions. */\n  readonly actions: GoalLaunchActions;\n}\n\n/** The per-Session launcher cache both entry points share. */\nexport interface GoalLaunchers {\n  /** Returns the launcher bound to one sessionId, creating it on first use. */\n  get(sessionId: string): GoalLauncher;\n}\n\nconst IDLE: GoalLaunchState = { phase: \"idle\" };\n\n/** Reads a human-facing message from a rejected submission. */\nfunction failureMessage(error: unknown): string {\n  if (typeof error === \"object\" && error !== null) {\n    const { message, code } = error as { message?: unknown; code?: unknown };\n    if (typeof message === \"string\" && message.length > 0) {\n      return message;\n    }\n    if (typeof code === \"string\" && code.length > 0) {\n      return code;\n    }\n  }\n  return String(error);\n}\n\n/**\n * Creates one Session's launcher over the command port. The state machine\n * is the whole contract: request opens the confirmation, cancel closes it\n * with nothing sent, and confirm moves to pending, submits the fixed\n * command line exactly once, and settles as launched or refused.\n */\nexport function createGoalLauncher(port: CommandPort, sessionId: string): GoalLauncher {\n  const state = createSnapshotStore<GoalLaunchState>(IDLE);\n  const phase = (): GoalLaunchState[\"phase\"] => state.getSnapshot().phase;\n  return {\n    sessionId,\n    objective: MILESTONE_GOAL_OBJECTIVE,\n    state,\n    actions: {\n      request(): void {\n        if (phase() === \"confirming\" || phase() === \"pending\") {\n          return;\n        }\n        state.set({ phase: \"confirming\" });\n      },\n      cancel(): void {\n        if (phase() !== \"confirming\") {\n          return;\n        }\n        state.set(IDLE);\n      },\n      async confirm(): Promise<void> {\n        if (phase() !== \"confirming\") {\n          return;\n        }\n        state.set({ phase: \"pending\" });\n        let next: GoalLaunchState;\n        try {\n          const outcome = await port.execute(sessionId, MILESTONE_GOAL_COMMAND_LINE);\n          if (outcome.kind === \"unknown-command\") {\n            next = { phase: \"refused\", refusal: { kind: \"unavailable\" } };\n          } else if (outcome.result.kind === \"error\") {\n            next = { phase: \"refused\", refusal: { kind: \"refused\", text: outcome.result.text } };\n          } else {\n            next = { phase: \"launched\" };\n          }\n        } catch (error) {\n          next = { phase: \"refused\", refusal: { kind: \"failed\", message: failureMessage(error) } };\n        }\n        state.set(next);\n      },\n    },\n  };\n}\n\n/**\n * Creates the per-Session launcher cache. A launcher holds no watch or\n * subscription of its own, so the cache needs no teardown: a launcher\n * whose surface unmounts keeps its last state for the Session's next mount.\n */\nexport function createGoalLaunchers(port: CommandPort): GoalLaunchers {\n  const launchers = new Map<string, GoalLauncher>();\n  return {\n    get(sessionId: string): GoalLauncher {\n      const cached = launchers.get(sessionId);\n      if (cached !== undefined) {\n        return cached;\n      }\n      const launcher = createGoalLauncher(port, sessionId);\n      launchers.set(sessionId, launcher);\n      return launcher;\n    },\n  };\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/host.ts",
      "content": "/**\n * Host entry of dsh-plugin-strict-spec: the cordis plugin row the bundle\n * patch inserts. It owns the plugin's one host-side capability, the built-in\n * strict tooling provision: while the single `builtinTooling` switch is\n * enabled (its default), the entry registers the bundled-skill provider onto\n * the host's `ctx.skills` registry, which serves the strict skill packages\n * from the plugin's own dist assets, rewrites their CLI commands to the\n * bundled strict-spec-cli, and marks each built-in catalog entry with a\n * provenance suffix naming the plugin and its version. While the switch is\n * disabled the entry applies nothing, so the plugin is exactly the read-only\n * viewer. The entry never mutates workflow files and never writes outside\n * its own package.\n */\nimport { readFileSync } from \"node:fs\";\nimport { fileURLToPath } from \"node:url\";\nimport path from \"node:path\";\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport Schema from \"@deepseek-ai/schemastery\";\nimport { buildProvenanceMarker, createBuiltinToolingProvider } from \"./host/builtinTooling.ts\";\n\n/** The host-owned skill registry the built-in tooling registers onto. */\nexport const inject = [\"skills\"];\n\n/** Built-in tooling configuration: one master switch, on by default. */\nexport interface Config {\n  /**\n   * Enable the built-in strict skill and CLI provision. Skills and CLI are\n   * one provision — the served skill bodies are the bundled CLI's only\n   * session entry point — so one switch governs both, and turning it off\n   * leaves the viewer-only plugin and hands precedence back to any external\n   * installation.\n   */\n  builtinTooling?: boolean;\n}\n\n/** Validated configuration schema for the plugin row's config. */\nexport const Config = Schema.object({\n  builtinTooling: Schema.boolean()\n    .default(true)\n    .description(\"Serve the built-in strict skills and strict-spec-cli from this plugin.\"),\n});\n\n/**\n * Read the installed plugin's version from the package.json beside dist, so\n * the provenance marker reports the version actually serving. A missing,\n * unparsable, or version-less manifest degrades to a marker naming the\n * version unknown rather than failing the provision. Exported for the host\n * suite's degradation cases.\n */\nexport function readPluginVersion(distDir: string): string {\n  try {\n    const manifest = JSON.parse(readFileSync(path.join(distDir, \"..\", \"package.json\"), \"utf8\")) as { version?: string };\n    return manifest.version && manifest.version.length > 0 ? manifest.version : \"unknown\";\n  } catch {\n    return \"unknown\";\n  }\n}\n\n/**\n * Register the built-in tooling behind its switch. The bundled assets are\n * resolved relative to this module — the built host.js sits inside dist/\n * beside the `skills/` and `cli/` assets the build writes — and the CLI\n * invocation closes over the running host's own node executable\n * (`process.execPath`), so neither PATH lookups nor a global install are\n * involved. Disposing the fiber unregisters the provider and invalidates\n * skill catalogs, which is what restores external copies after the switch\n * turns off.\n *\n * @param ctx - host root context carrying the skills service.\n * @param config - validated plugin row config; absence keeps the default on.\n */\nexport function apply(ctx: Context, config: Config = {}): void {\n  if (config.builtinTooling === false) return;\n  const distDir = path.dirname(fileURLToPath(import.meta.url));\n  ctx.skills.registerProvider(() =>\n    createBuiltinToolingProvider({\n      skillsDir: path.join(distDir, \"skills\"),\n      cliPath: path.join(distDir, \"cli\", \"strict-spec-cli.js\"),\n      execPath: process.execPath,\n      provenanceMarker: buildProvenanceMarker(readPluginVersion(distDir)),\n    }),\n  );\n}\n"
    },
    {
      "path": "plugins/dsh-strict-spec/src/host/builtinTooling.ts",
      "content": "/**\n * Built-in strict tooling for the dsh plugin host entry.\n *\n * The module is deliberately dsh-free at runtime: it shapes plain objects\n * against the `SkillProvider` contract of `@deepseek-ai/dsh-skill` through\n * type-only imports, because the provider is handed to the host-owned\n * `ctx.skills` service, which owns the registry. Everything the module needs\n * at runtime comes from its parameters — the bundled assets' absolute\n * locations and the running host's executable — so a suite can exercise the\n * whole provision against fixture directories without a dsh host.\n *\n * Two behaviors are contract-bearing rather than incidental:\n *\n * - Candidates are served at {@link BUILTIN_TOOLING_RANK}, the pinned dsh\n *   line's bundled band, so built-in copies are a fallback: within one\n *   registry layer every filesystem skill root rank (project 100 through user\n *   500) beats the bundled band and the external copy of a same-name skill\n *   wins, and across layers a preset's local discovery registers nearer than\n *   this deployment-level provider, so a session with an external copy runs\n *   the external tooling. Only a name no external root offers falls through\n *   to the built-in copy, which is what keeps zero-install machines working.\n *   The `source` field stays \"bundled\" because it is origin metadata, not\n *   precedence.\n * - Skill bodies are shipped byte-identical to the repository `skills/`\n *   packages and adapted only at serve time: every bare `strict-spec-cli`\n *   command token is rewritten into a direct invocation of the bundled CLI\n *   through the running host's node executable, so the repository packages\n *   remain the single authored source and no global install is required.\n */\nimport { readFile, readdir } from \"node:fs/promises\";\nimport path from \"node:path\";\nimport type {\n  SkillCandidate,\n  SkillDefinition,\n  SkillProvider,\n} from \"@deepseek-ai/dsh-skill\";\n\n/** The provider's name in the host's `ctx.skills` registry. */\nexport const BUILTIN_TOOLING_PROVIDER_NAME = \"strict-spec-plugin\";\n\n/**\n * Candidate rank of the pinned dsh line's bundled band: within one registry\n * layer the resolver picks the lowest rank for a duplicate name, and the\n * filesystem provider's roots occupy 100 (project-dsh) through 500\n * (user-agents), so the bundled band loses every same-layer duel against an\n * external copy. Across layers a preset's local discovery registers nearer\n * than this deployment-level provider, which makes external copies win there\n * too — the built-in copies serve only names no external root offers.\n */\nexport const BUILTIN_TOOLING_RANK = 600;\n\n/** The file name a bundled skill package carries its body in. */\nexport const SKILL_BODY_FILE = \"SKILL.md\";\n\n/** Frontmatter fence exactly as the repository skill packages declare it. */\nconst FRONTMATTER_FENCE = \"---\";\n\n/** The kebab-case grammar the pinned registry accepts for a skill name. */\nconst SKILL_NAME_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;\n\n/**\n * The bare `strict-spec-cli` token every authored skill body states its\n * commands with. The lookarounds keep the match from firing inside a longer\n * reference: a word or hyphen on either side marks an identifier, and a\n * trailing dot marks a file name such as `strict-spec-cli.js`, so only the\n * bare command token — followed by a space, end of line, or punctuation — is\n * rewritten.\n */\nexport const CLI_TOKEN_PATTERN = /(?<![\\w-])strict-spec-cli(?![\\w.-])/g;\n\n/**\n * Characters that stay one shell word and one YAML plain scalar unquoted.\n * Anything else — spaces, quotes, `$`, backticks, braces, non-ASCII — makes\n * the path quote itself as a JSON string so the rewritten command line is\n * copy-runnable in a shell and stays readable in prose and YAML blocks.\n */\nconst SAFE_UNQUOTED_PATTERN = /^[A-Za-z0-9_@%+=:,./-]+$/;\n\n/** Invocation controls shared by every bundled candidate. */\nconst INVOCATION = { modelInvocable: true, userInvocable: true } as const;\n\n/** Parsed frontmatter of one bundled skill body. */\nexport interface SkillFrontmatter {\n  /** The kebab-case skill name the body declares. */\n  readonly name: string;\n  /** The single-line routing description the body declares. */\n  readonly description: string;\n  /** The instruction body after the closing fence. */\n  readonly body: string;\n}\n\n/** The absolute locations and runtime facts the provision closes over. */\nexport interface BuiltinToolingAssets {\n  /** Directory holding one `<name>/SKILL.md` per bundled skill. */\n  readonly skillsDir: string;\n  /** Absolute path of the bundled strict-spec-cli bundle. */\n  readonly cliPath: string;\n  /** Absolute path of the running host's node executable. */\n  readonly execPath: string;\n  /**\n   * Provenance marker appended to every built-in candidate's description, so\n   * the catalog distinguishes a built-in entry from an external one before\n   * any skill is loaded. See {@link buildProvenanceMarker}.\n   */\n  readonly provenanceMarker: string;\n}\n\n/**\n * Build the catalog provenance marker naming the plugin and its installed\n * version. The em dash keeps the marker reading as trailing provenance after\n * the authored routing text; the host entry derives the version from the\n * package.json sitting beside the bundled assets, so the marker reports the\n * version actually serving.\n */\nexport function buildProvenanceMarker(pluginVersion: string): string {\n  return ` — built-in (dsh plugin ${pluginVersion})`;\n}\n\n/** Quote one path for a command line, only when it needs quoting. */\nexport function quoteCommandPath(value: string): string {\n  return SAFE_UNQUOTED_PATTERN.test(value) ? value : JSON.stringify(value);\n}\n\n/** Build the invocation that replaces the bare CLI token in served bodies. */\nexport function buildCliInvocation(execPath: string, cliPath: string): string {\n  return `${quoteCommandPath(execPath)} ${quoteCommandPath(cliPath)}`;\n}\n\n/** Rewrite every bare CLI token in a skill body to the bundled invocation. */\nexport function rewriteCliToken(body: string, invocation: string): string {\n  return body.replace(CLI_TOKEN_PATTERN, invocation);\n}\n\n/**\n * Read the strict frontmatter the repository skill packages declare: a fence,\n * single-line `name` and `description` string values, an ignored remainder\n * such as the metadata block, and a closing fence. Returns `undefined` for\n * anything else — no frontmatter, a missing or empty required value, or a\n * name outside the kebab-case grammar — so the caller's failure mode is\n * omitting the skill, never guessing at its identity.\n */\nexport function parseSkillFrontmatter(text: string): SkillFrontmatter | undefined {\n  const lines = text.split(/\\r?\\n/);\n  if (lines[0] !== FRONTMATTER_FENCE) return undefined;\n  let name: string | undefined;\n  let description: string | undefined;\n  let closeIndex = -1;\n  for (let index = 1; index < lines.length; index += 1) {\n    const line = lines[index];\n    if (line === FRONTMATTER_FENCE) {\n      closeIndex = index;\n      break;\n    }\n    // First declaration wins: the ignored remainder (the metadata block)\n    // cannot override the identity fields above it.\n    if (name === undefined && line.startsWith(\"name:\")) {\n      name = line.slice(\"name:\".length).trim();\n    } else if (description === undefined && line.startsWith(\"description:\")) {\n      description = line.slice(\"description:\".length).trim();\n    }\n  }\n  if (closeIndex < 0) return undefined;\n  if (name === undefined || name.length === 0 || !SKILL_NAME_PATTERN.test(name)) return undefined;\n  if (description === undefined || description.length === 0) return undefined;\n  return { name, description, body: lines.slice(closeIndex + 1).join(\"\\n\") };\n}\n\n/** One bundled skill discovered in the plugin's assets. */\nexport interface BundledSkillRecord {\n  /** Kebab-case skill name from the body's frontmatter. */\n  readonly name: string;\n  /** Routing description from the body's frontmatter. */\n  readonly description: string;\n  /** Absolute path of the bundled SKILL.md. */\n  readonly filePath: string;\n}\n\n/**\n * List the bundled skills an assets directory holds. A directory without a\n * parseable SKILL.md is omitted; a skills directory that cannot be read at\n * all yields an empty list, so a broken or partial installation degrades to\n * offering nothing rather than failing the host.\n */\nexport async function listBundledSkills(skillsDir: string): Promise<readonly BundledSkillRecord[]> {\n  let entries;\n  try {\n    entries = await readdir(skillsDir, { withFileTypes: true });\n  } catch {\n    return [];\n  }\n  const records: BundledSkillRecord[] = [];\n  for (const entry of entries) {\n    if (!entry.isDirectory()) continue;\n    const filePath = path.join(skillsDir, entry.name, SKILL_BODY_FILE);\n    let text: string;\n    try {\n      text = await readFile(filePath, \"utf8\");\n    } catch {\n      continue;\n    }\n    const parsed = parseSkillFrontmatter(text);\n    if (parsed === undefined) continue;\n    records.push({ name: parsed.name, description: parsed.description, filePath });\n  }\n  records.sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0));\n  return records;\n}\n\n/**\n * Create the bundled-skill provider the host entry registers on `ctx.skills`\n * while the built-in tooling switch is enabled. `list()` reads the assets\n * directory on every call so a repaired installation recovers without a\n * host restart, and `get()` re-reads and re-parses the body so a file that\n * disappeared or broke since listing resolves to `undefined` instead of a\n * stale definition.\n */\nexport function createBuiltinToolingProvider(assets: BuiltinToolingAssets): SkillProvider {\n  const invocation = buildCliInvocation(assets.execPath, assets.cliPath);\n  return {\n    name: BUILTIN_TOOLING_PROVIDER_NAME,\n    async list(): Promise<readonly SkillCandidate[]> {\n      const records = await listBundledSkills(assets.skillsDir);\n      return records.map((record): SkillCandidate => ({\n        name: record.name,\n        description: `${record.description}${assets.provenanceMarker}`,\n        invocation: INVOCATION,\n        source: \"bundled\",\n        provider: BUILTIN_TOOLING_PROVIDER_NAME,\n        resourceBase: { kind: \"directory\", path: path.dirname(record.filePath) },\n        rank: BUILTIN_TOOLING_RANK,\n        locator: record.filePath,\n      }));\n    },\n    async get(candidate: SkillCandidate): Promise<SkillDefinition | undefined> {\n      let text: string;\n      try {\n        text = await readFile(String(candidate.locator), \"utf8\");\n      } catch {\n        return undefined;\n      }\n      const parsed = parseSkillFrontmatter(text);\n      if (parsed === undefined || parsed.name !== candidate.name) return undefined;\n      return {\n        name: parsed.name,\n        description: `${parsed.description}${assets.provenanceMarker}`,\n        invocation: INVOCATION,\n        source: \"bundled\",\n        provider: BUILTIN_TOOLING_PROVIDER_NAME,\n        resourceBase: { kind: \"directory\", path: path.dirname(String(candidate.locator)) },\n        content: rewriteCliToken(parsed.body, invocation),\n      };\n    },\n  };\n}\n"
    }
